const en = [];
const ar = [];

export const articlesContent = { tr, en, ar };

const DEFAULT_NOTES = {
  tr: 'Bilgilendirme: Bu makale genel bilgilendirme amacı taşır; hukuki görüş veya danışmanlık niteliğinde değildir.',
  en: 'Disclaimer: This article is for general informational purposes only and does not constitute legal advice. A case-specific review should be carried out based on the facts and documents of the matter.',
  ar: 'تنويه: هذه المقالة لأغراض معلوماتية عامة فقط ولا تشكل استشارة قانونية. ويجب إجراء تقييم خاص بكل حالة وفق الوقائع والمستندات ذات الصلة.',
};

export const supportedLocales = Object.keys(articlesContent);

export function isSupportedLocale(locale) {
  return supportedLocales.includes(locale);
}

export function getArticles(locale = 'tr') {
  const baseList = articlesContent.tr || [];

  if (locale === 'tr' || !isSupportedLocale(locale)) {
    return baseList;
  }

  const localeList = articlesContent[locale] || [];
  const bySlug = new Map(localeList.map((item) => [item.slug, item]));

  return baseList.map((item) => {
    const translated = bySlug.get(item.slug) || {};

    return {
      ...item,
      ...translated,
      slug: item.slug,
      icon: translated.icon || item.icon,
      title: translated.title || item.title,
      summary: translated.summary || item.summary,
      introText: translated.introText || item.introText,
      sections:
        Array.isArray(translated.sections) && translated.sections.length > 0
          ? translated.sections
          : item.sections,
      note: translated.note || DEFAULT_NOTES[locale] || DEFAULT_NOTES.en,
    };
  });
}

export function getArticleBySlug(slug, locale = 'tr') {
  const list = getArticles(locale);
  return list.find((item) => item.slug === slug) || null;
}

export function getArticleSlugs(locale = 'tr') {
  return getArticles(locale).map((item) => item.slug);
}